// === Tab: mySketch ===
// by SamuelYAN
// more works //
// https://twitter.com/SamuelAnn0924
// https://www.instagram.com/samuel_yan_1990/

// reference: https://gorillasun.de/blog/Radial-Perlin-Noise-and-Generative-Tree-Rings
// reference: https://www.reddit.com/r/processing/comments/awzkgd/tree_rings_made_with_perlin_noise/

// Shape of TIME

var angle;
var color1, color2, grad;
var Stroke_Weight;
var resolution;
var Noise_Scale;
var Vinyl_Size;

let radius;
let t = 0;
let timer = 0;
let filter;
let mySize;

/** OPC START **/
OPC.slider('Vinyl_Records', Math.floor(Math.random() * 100), 0, 100, 1); //seed
OPC.slider('stylus', 40, 20, 60, 5); // rings
OPC.slider('my_label', 2, 0, 6, 0.1); // color
OPC.slider('environmental_noise', 200, 100, 300, 20); // point_num
/** OPC END **/

let PVinyl_Records = Vinyl_Records;
let Pstylus = stylus;
let Pmy_label = my_label;
let Penvironmental_noise = environmental_noise;

function setup() {
	randomSeed(Vinyl_Records);
	noiseSeed(Vinyl_Records);
	mySize = max(windowWidth, windowHeight);
	createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 360, 100, 100, 100);
	background(0, 0, 95, 100);
	filter = new makeFilter();
	Stroke_Weight = 1;
	resolution = 1;
	Noise_Scale = 5;
}



function draw() {
	randomSeed(Vinyl_Records);
	noiseSeed(Vinyl_Records);
	Vinyl_Size = 2;
	radius = mySize / 5 * Vinyl_Size;
	let num = int(random(int(stylus / 3), int(stylus / 3 * 2)));
	push();
	translate(width / 2, height / 2);
	angle = my_label;
	rotate(random(TAU)+t);
	translate(Noise_Scale / 2, Noise_Scale / 2);

	let r_plus = int(radius / stylus);

	for (r = 30; r < radius; r += r_plus) {
		if (r == 30 + r_plus * num) {
			color1 = color(int(360 * (angle / TAU)), 100, 90, 0);
			color2 = color(int(360 * (angle / TAU)), 100, 90, 100);
			fill(0, 100, 100, 50);
			stroke(int(360 * (angle / TAU)), 100, 90, 50);
			strokeWeight(Stroke_Weight*2);
		} else {
			color1 = color(0, 0, 20, 0);
			color2 = color(0, 0, 20, 100);
			fill(0, 0, 20, 10);
			stroke(0, 0, 20, 10);
			strokeWeight(Stroke_Weight);
		}
		beginShape();

		for (a = -TAU / environmental_noise; a < TAU + TAU / environmental_noise; a += TAU / environmental_noise) {
			let x = r * cos(a + t);
			let y = r * sin(a + t);
			let n = map(noise(x * resolution, y * resolution), 0, 1, -Noise_Scale, 0);

			// gradient color 
			grad = drawingContext.createRadialGradient(n, n, r - random(0.1, 0.15), n, n, r);
			grad.addColorStop(0, color1);
			grad.addColorStop(1, color2);
			drawingContext.fillStyle = grad;

			// shape
			curveVertex(x + n, y + n);

			if (random() > 0.75 - 0.25 * sin(r)) {
				endShape();
				beginShape();
			}
		}
		endShape();
	}
	pop();

	timer++;
	if (timer < 25) {
		angle += TAU / 360;
		t += 0.01;
		image(overAllTexture, 0, 0);
	} else {
		angle += 0;
		t += 0;
	}


	if (PVinyl_Records != Vinyl_Records ||
		Pstylus != stylus ||
		Pmy_label != my_label ||
		Penvironmental_noise != environmental_noise ) {

		PVinyl_Records = Vinyl_Records;
		Pstylus = stylus;
		Pmy_label = my_label;
		Penvironmental_noise = environmental_noise;

		randomSeed(Vinyl_Records);
		noiseSeed(Vinyl_Records);
		background(0, 0, 95, 100);
		timer = 0;
		Stroke_Weight = int(random(1,3));
	  resolution = int(random(0.5,5));
	  Noise_Scale = int(random(2,10));
	}
}

function makeFilter() {
	// noiseのフィルターをつくる
	colorMode(HSB, 360, 100, 100, 100);
	drawingContext.shadowColor = color(0, 0, 5, 95);
	overAllTexture = createGraphics(windowWidth, windowHeight);
	overAllTexture.loadPixels();
	for (var i = 0; i < width; i++) {
		for (var j = 0; j < height; j++) {
			overAllTexture.set(
				i,
				j,
				color(
					0,
					0,
					99,
					noise(i / 3, j / 3, (i * j) / 50) * random(5, 15)
				)
			);
		}
	}
	overAllTexture.updatePixels();
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("Shape of TIME_03_one second sound", "png");
	}
}

